package com.harish.student_management.service;
import com.harish.student_management.dto.*; import com.harish.student_management.entity.*; import com.harish.student_management.repository.*; import com.harish.student_management.exception.ResourceNotFoundException; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class JourneyTimelineServiceImpl implements JourneyTimelineService { private final StudentRepository students; private final AttendanceRepository attendance; private final BusTripEventRepository busEvents; private final StudentAchievementRepository achievements; private final AssignmentRepository assignments;
 public JourneyTimelineDto today(Long id){return forDate(id,LocalDate.now());}
 public JourneyTimelineDto forDate(Long id,LocalDate date){Student s=students.findById(id).orElseThrow(()->new ResourceNotFoundException("Student not found"));List<JourneyEventDto> out=new ArrayList<>(); busEvents.findAll().stream().filter(e->e.getStudent()!=null&&e.getStudent().getId().equals(id)&&e.getOccurredAt().toLocalDate().equals(date)).forEach(e->out.add(event(e.getOccurredAt().toLocalTime(),e.getEventType(),label(e.getEventType()),e.getDetails(),"BUS"))); if(s.getSection()!=null)attendance.findByStudentIdAndClassId(id,s.getSection().getClassEntity().getId()).stream().filter(a->date.equals(a.getAttendanceDate())).forEach(a->out.add(event(a.getMarkedAt()==null?LocalTime.MIDNIGHT:a.getMarkedAt().toLocalTime(),"ATTENDANCE","Attendance marked",a.getStatus(),"ATTENDANCE"))); achievements.findByStudentIdOrderByAchievementDateDesc(id).stream().filter(a->date.equals(a.getAchievementDate())).forEach(a->out.add(event(LocalTime.MIDNIGHT,"ACHIEVEMENT",a.getTitle(),a.getDescription(),"ACHIEVEMENT")));out.sort(Comparator.comparing(JourneyEventDto::getTime));return JourneyTimelineDto.builder().studentId(id).studentName(s.getName()).date(date).events(out).build();}
 private JourneyEventDto event(LocalTime t,String type,String title,String d,String source){return JourneyEventDto.builder().time(t).type(type).title(title).description(d).source(source).build();}private String label(String t){return switch(t){case "CHILD_BOARDED"->"Child boarded bus";case "SCHOOL_REACHED"->"Reached school";case "BUS_STARTED"->"Bus started";case "CHILD_DROPPED"->"Dropped safely";default->t;};}}
